pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    function setUp() public { c = new RoundFactory(); }
    function testRegression_property() public {
        vm.prank(address(this));
        c.initialize();

        address dummyRound = address(0x1234);
        vm.prank(address(this));
        c.updateRoundImplementation(payable(dummyRound));

        vm.prank(address(this));
        c.updateAlloSettings(address(0x0000000000000000000000000000000000000001));

        address operator = address(0xdead);
        assertTrue(c.alloSettings() == address(0x0000000000000000000000000000000000000001));
    }
}
